--
-- Name: cards; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.cards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    player_id uuid NOT NULL,
    match_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    team_id uuid NOT NULL,
    card_type character varying(20) NOT NULL,
    minute integer,
    reason text,
    issued_by uuid NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    source_event_id uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    CONSTRAINT cards_type_check CHECK (((card_type)::text = ANY ((ARRAY['YELLOW'::character varying, 'RED'::character varying])::text[])))
);


ALTER TABLE public.cards OWNER TO sfl;

--
-- Name: complaint_appeals; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.complaint_appeals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    complaint_id uuid NOT NULL,
    submitted_by uuid NOT NULL,
    description text NOT NULL,
    evidence text,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    decision_reason text,
    original_decision jsonb,
    CONSTRAINT complaint_appeals_description_check CHECK (((length(TRIM(BOTH FROM description)) >= 10) AND (length(TRIM(BOTH FROM description)) <= 4000))),
    CONSTRAINT complaint_appeals_rejection_reason CHECK ((((status)::text <> 'REJECTED'::text) OR (length(TRIM(BOTH FROM COALESCE(decision_reason, ''::text))) > 0))),
    CONSTRAINT complaint_appeals_review_state CHECK (((((status)::text = 'PENDING'::text) AND (reviewed_by IS NULL) AND (reviewed_at IS NULL)) OR (((status)::text = ANY ((ARRAY['APPROVED'::character varying, 'REJECTED'::character varying])::text[])) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT complaint_appeals_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[])))
);


ALTER TABLE public.complaint_appeals OWNER TO sfl;

