--
-- Name: lineups; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.lineups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    match_id uuid NOT NULL,
    team_id uuid NOT NULL,
    player_id uuid NOT NULL,
    "position" character varying(50),
    jersey_number integer,
    is_starting boolean DEFAULT true NOT NULL,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lineups_jersey_check CHECK (((jersey_number IS NULL) OR ((jersey_number >= 1) AND (jersey_number <= 99))))
);


ALTER TABLE public.lineups OWNER TO sfl;

--
-- Name: match_bracket_qualification_sources; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.match_bracket_qualification_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slot_id uuid NOT NULL,
    draw_version_id uuid NOT NULL,
    side character varying(4) NOT NULL,
    group_id uuid NOT NULL,
    group_rank smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT match_bracket_qualification_sources_group_rank_check CHECK ((group_rank > 0)),
    CONSTRAINT match_bracket_qualification_sources_side_check CHECK (((side)::text = ANY ((ARRAY['HOME'::character varying, 'AWAY'::character varying])::text[])))
);


ALTER TABLE public.match_bracket_qualification_sources OWNER TO sfl;

--
-- Name: match_bracket_slots; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.match_bracket_slots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tournament_id uuid NOT NULL,
    draw_version_id uuid NOT NULL,
    round_number smallint NOT NULL,
    "position" smallint NOT NULL,
    home_team_id uuid,
    away_team_id uuid,
    home_source_slot_id uuid,
    away_source_slot_id uuid,
    home_resolved boolean DEFAULT false NOT NULL,
    away_resolved boolean DEFAULT false NOT NULL,
    winner_team_id uuid,
    match_id uuid,
    status character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    slot_type character varying(20) DEFAULT 'STANDARD'::character varying NOT NULL,
    home_source_outcome character varying(10) DEFAULT 'WINNER'::character varying NOT NULL,
    away_source_outcome character varying(10) DEFAULT 'WINNER'::character varying NOT NULL,
    CONSTRAINT match_bracket_away_source_outcome_check CHECK (((away_source_outcome)::text = ANY ((ARRAY['WINNER'::character varying, 'LOSER'::character varying])::text[]))),
    CONSTRAINT match_bracket_different_teams CHECK (((home_team_id IS NULL) OR (away_team_id IS NULL) OR (home_team_id <> away_team_id))),
    CONSTRAINT match_bracket_home_source_outcome_check CHECK (((home_source_outcome)::text = ANY ((ARRAY['WINNER'::character varying, 'LOSER'::character varying])::text[]))),
    CONSTRAINT match_bracket_slot_type_check CHECK (((slot_type)::text = ANY ((ARRAY['STANDARD'::character varying, 'THIRD_PLACE'::character varying])::text[]))),
    CONSTRAINT match_bracket_slots_position_check CHECK (("position" > 0)),
    CONSTRAINT match_bracket_slots_round_number_check CHECK ((round_number > 0)),
    CONSTRAINT match_bracket_slots_status_check CHECK (((status)::text = ANY ((ARRAY['WAITING'::character varying, 'READY'::character varying, 'BYE'::character varying, 'COMPLETED'::character varying])::text[])))
);


ALTER TABLE public.match_bracket_slots OWNER TO sfl;

--
-- Name: match_clock_states; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.match_clock_states (
    match_id uuid NOT NULL,
    phase character varying(32) DEFAULT 'NOT_STARTED'::character varying NOT NULL,
    elapsed_seconds integer DEFAULT 0 NOT NULL,
    total_elapsed_seconds integer DEFAULT 0 NOT NULL,
    is_running boolean DEFAULT false NOT NULL,
    started_at timestamp with time zone,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    CONSTRAINT match_clock_running_started_check CHECK (((is_running AND (started_at IS NOT NULL)) OR ((NOT is_running) AND (started_at IS NULL)))),
    CONSTRAINT match_clock_states_elapsed_seconds_check CHECK ((elapsed_seconds >= 0)),
    CONSTRAINT match_clock_states_phase_check CHECK (((phase)::text = ANY ((ARRAY['NOT_STARTED'::character varying, 'FIRST_HALF'::character varying, 'HALF_TIME'::character varying, 'SECOND_HALF'::character varying, 'REGULATION_COMPLETE'::character varying, 'EXTRA_TIME_FIRST_HALF'::character varying, 'EXTRA_TIME_HALF_TIME'::character varying, 'EXTRA_TIME_SECOND_HALF'::character varying, 'EXTRA_TIME_COMPLETE'::character varying, 'PENALTIES'::character varying, 'ENDED'::character varying])::text[]))),
    CONSTRAINT match_clock_states_total_elapsed_seconds_check CHECK ((total_elapsed_seconds >= 0)),
    CONSTRAINT match_clock_states_version_check CHECK ((version >= 0))
);


ALTER TABLE public.match_clock_states OWNER TO sfl;

