    CONSTRAINT match_bracket_slots_status_check CHECK (((status)::text = ANY (ARRAY[('WAITING'::character varying)::text, ('READY'::character varying)::text, ('BYE'::character varying)::text, ('COMPLETED'::character varying)::text])))
);


