    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT match_event_discipline_outbox_action_check CHECK (((action)::text = ANY (ARRAY[('ISSUE_CARD'::character varying)::text, ('VOID_CARD'::character varying)::text])))
);


