    CONSTRAINT match_forfeit_decisions_check1 CHECK ((home_score <> away_score)),
    CONSTRAINT match_forfeit_decisions_home_score_check CHECK ((home_score >= 0)),
    CONSTRAINT match_forfeit_decisions_policy_check CHECK (((policy)::text = ANY (ARRAY[('WALKOVER'::character varying)::text, ('ORGANIZER_DECISION'::character varying)::text])))
);


