    CONSTRAINT matches_status_check CHECK (((status)::text = ANY (ARRAY[('UNSCHEDULED'::character varying)::text, ('SCHEDULED'::character varying)::text, ('LINEUP_CONFIRMED'::character varying)::text, ('IN_PROGRESS'::character varying)::text, ('FINISHED'::character varying)::text, ('VERIFIED'::character varying)::text, ('LOCKED'::character varying)::text, ('CANCELLED'::character varying)::text, ('POSTPONED'::character varying)::text]))),
    CONSTRAINT matches_teams_check CHECK (((home_team_id IS NULL) OR (away_team_id IS NULL) OR (home_team_id <> away_team_id)))
);


