    draw_version_id uuid NOT NULL,
    group_id uuid NOT NULL,
    tie_key text NOT NULL,
    tied_team_ids uuid[] NOT NULL,
    drawn_order uuid[] NOT NULL,
    witness_name text NOT NULL,
    reason text NOT NULL,
    drawn_by uuid NOT NULL,
    drawn_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT match_group_lot_draws_reason_check CHECK (((length(TRIM(BOTH FROM reason)) >= 10) AND (length(TRIM(BOTH FROM reason)) <= 1000))),
    CONSTRAINT match_group_lot_draws_witness_name_check CHECK (((length(TRIM(BOTH FROM witness_name)) >= 2) AND (length(TRIM(BOTH FROM witness_name)) <= 120)))
);


