    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    status character varying(20) DEFAULT 'APPROVED'::character varying NOT NULL,
    CONSTRAINT match_results_scores_check CHECK (((home_score >= 0) AND (away_score >= 0))),
    CONSTRAINT match_results_status_check CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text])))
);


