CREATE TABLE public.matches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tournament_id uuid NOT NULL,
    home_team_id uuid,
    away_team_id uuid,
    match_date timestamp with time zone,
    venue character varying(255),
    round character varying(100),
    status character varying(50) DEFAULT 'SCHEDULED'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    draw_version_id uuid,
    fixture_key text,
    group_id uuid,
    stage character varying(20),
    round_number smallint,
    leg smallint,
    CONSTRAINT matches_fixture_leg_check CHECK (((leg IS NULL) OR (leg = ANY (ARRAY[1, 2])))),
    CONSTRAINT matches_fixture_round_number_check CHECK (((round_number IS NULL) OR (round_number > 0))),
    CONSTRAINT matches_fixture_stage_check CHECK (((stage IS NULL) OR ((stage)::text = ANY (ARRAY[('GROUP'::character varying)::text, ('KNOCKOUT'::character varying)::text])))),
    CONSTRAINT matches_status_check CHECK (((status)::text = ANY (ARRAY[('UNSCHEDULED'::character varying)::text, ('SCHEDULED'::character varying)::text, ('LINEUP_CONFIRMED'::character varying)::text, ('IN_PROGRESS'::character varying)::text, ('FINISHED'::character varying)::text, ('VERIFIED'::character varying)::text, ('LOCKED'::character varying)::text, ('CANCELLED'::character varying)::text, ('POSTPONED'::character varying)::text]))),
    CONSTRAINT matches_teams_check CHECK (((home_team_id IS NULL) OR (away_team_id IS NULL) OR (home_team_id <> away_team_id)))
);


ALTER TABLE public.matches OWNER TO sfl;

