--
-- Name: prevent_team_registration_submission_order_change(); Type: FUNCTION; Schema: public; Owner: sfl
--

CREATE FUNCTION public.prevent_team_registration_submission_order_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
          BEGIN
            IF OLD.submission_sequence IS NOT NULL AND NEW.submission_sequence IS DISTINCT FROM OLD.submission_sequence THEN
              RAISE EXCEPTION 'submission_sequence is immutable after submission' USING ERRCODE = '23514';
            END IF;
            IF OLD.submitted_at IS NOT NULL AND NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN
              RAISE EXCEPTION 'submitted_at is immutable after submission' USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
          END;
          $$;


ALTER FUNCTION public.prevent_team_registration_submission_order_change() OWNER TO sfl;

--
-- Name: update_club_request_updated_at_column(); Type: FUNCTION; Schema: public; Owner: sfl
--

CREATE FUNCTION public.update_club_request_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
          BEGIN
            NEW.updated_at = CURRENT_TIMESTAMP;
            RETURN NEW;
          END;
          $$;


