    tournament_name character varying(255),
    conflict_tournament_id uuid,
    conflict_tournament_name character varying(255),
    status_reason text,
    CONSTRAINT tournament_player_invitation_jersey_check CHECK (((proposed_jersey_number IS NULL) OR ((proposed_jersey_number >= 1) AND (proposed_jersey_number <= 99)))),
    CONSTRAINT tournament_player_invitation_keeper_check CHECK (((is_goalkeeper = false) OR ((lineup_role)::text = 'STARTER'::text))),
    CONSTRAINT tournament_player_invitation_lineup_check CHECK (((lineup_role)::text = ANY ((ARRAY['STARTER'::character varying, 'SUBSTITUTE'::character varying])::text[]))),
    CONSTRAINT tournament_player_invitation_role_check CHECK (((competition_role)::text = ANY ((ARRAY['PLAYER'::character varying, 'PLAYING_CAPTAIN'::character varying, 'VICE_CAPTAIN'::character varying])::text[]))),
    CONSTRAINT tournament_player_invitation_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACCEPTED'::character varying, 'DECLINED'::character varying, 'EXPIRED'::character varying, 'CANCELLED'::character varying, 'CONFLICTED'::character varying, 'INVALIDATED'::character varying, 'WITHDRAWN'::character varying])::text[])))
);


ALTER TABLE public.tournament_player_invitations OWNER TO sfl;

--
-- Name: tournament_player_withdrawal_requests; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournament_player_withdrawal_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invitation_id uuid NOT NULL,
    player_user_id uuid NOT NULL,
    reason text NOT NULL,
    status character varying(16) DEFAULT 'PENDING'::character varying NOT NULL,
    desired_decision character varying(16),
    decision_note text,
    decided_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_player_withdrawal_requests_desired_decision_check CHECK (((desired_decision)::text = ANY ((ARRAY['APPROVED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT tournament_player_withdrawal_requests_reason_check CHECK ((length(btrim(reason)) >= 5)),
    CONSTRAINT tournament_player_withdrawal_requests_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'PROCESSING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[])))
);


ALTER TABLE public.tournament_player_withdrawal_requests OWNER TO sfl;

--
-- Name: tournament_registration_drafts; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournament_registration_drafts (
    team_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    updated_by uuid NOT NULL,
    roster jsonb DEFAULT '[]'::jsonb NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    registration_id uuid,
    base_version integer,
    editing_submitted boolean DEFAULT false NOT NULL,
    draft_state character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    CONSTRAINT tournament_registration_drafts_draft_state_check CHECK (((draft_state)::text = ANY ((ARRAY['DRAFT'::character varying, 'DRAFT_CHANGES'::character varying])::text[]))),
    CONSTRAINT tournament_registration_drafts_roster_check CHECK ((jsonb_typeof(roster) = 'array'::text))
);


ALTER TABLE public.tournament_registration_drafts OWNER TO sfl;

