    CONSTRAINT tournament_ranking_criterion_check CHECK (((criterion)::text = ANY ((ARRAY['POINTS'::character varying, 'GOAL_DIFFERENCE'::character varying, 'GOALS_FOR'::character varying, 'HEAD_TO_HEAD'::character varying, 'FAIR_PLAY'::character varying, 'LOT_DRAW'::character varying])::text[])))
);


ALTER TABLE public.tournament_ranking_criteria OWNER TO sfl;

--
-- Name: tournament_registration_control_audit; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournament_registration_control_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tournament_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    action character varying(20) NOT NULL,
    previous_status character varying(50) NOT NULL,
    new_status character varying(50) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_registration_control_audit_action_check CHECK (((action)::text = ANY ((ARRAY['TEST_CLOSE'::character varying, 'TEST_REOPEN'::character varying])::text[])))
);


ALTER TABLE public.tournament_registration_control_audit OWNER TO sfl;

--
-- Name: tournament_registration_reservations; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournament_registration_reservations (
    registration_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    team_id uuid NOT NULL,
    institution_id uuid NOT NULL,
    status character varying(40) DEFAULT 'PENDING'::character varying NOT NULL,
    persisted_in_organization boolean DEFAULT false NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '00:15:00'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    roster_player_ids uuid[] DEFAULT ARRAY[]::uuid[] NOT NULL,
    conflict_details jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT tournament_registration_reservations_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'WITHDRAWN'::character varying, 'WAITLIST'::character varying, 'CONFLICT_ADJUSTMENT_REQUIRED'::character varying])::text[])))
);


ALTER TABLE public.tournament_registration_reservations OWNER TO sfl;

