    tournament_id uuid NOT NULL,
    version integer NOT NULL,
    roster_data jsonb NOT NULL,
    locked_by uuid NOT NULL,
    locked_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_roster_lock_snapshot_teams_check CHECK (((jsonb_typeof(roster_data) = 'array'::text) AND (jsonb_array_length(roster_data) > 0)))
);


ALTER TABLE public.tournament_roster_lock_snapshots OWNER TO sfl;

