--
-- Name: tournament_rules; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournament_rules (
    tournament_id uuid NOT NULL,
    eligibility_description text DEFAULT ''::text NOT NULL,
    points_for_win integer DEFAULT 3 NOT NULL,
    points_for_draw integer DEFAULT 1 NOT NULL,
    points_for_loss integer DEFAULT 0 NOT NULL,
    advancing_teams_per_group integer DEFAULT 2 NOT NULL,
    yellow_cards_for_suspension integer DEFAULT 3 NOT NULL,
    suspension_matches integer DEFAULT 1 NOT NULL,
    complaint_window_hours integer DEFAULT 24 NOT NULL,
    minimum_rest_minutes integer DEFAULT 30 NOT NULL,
    match_duration_minutes integer DEFAULT 90 NOT NULL,
    forfeit_policy character varying(40) DEFAULT 'ORGANIZER_DECISION'::character varying NOT NULL,
    forfeit_winner_score integer DEFAULT 3 NOT NULL,
    forfeit_loser_score integer DEFAULT 0 NOT NULL,
    published_version integer DEFAULT 0 NOT NULL,
    published_at timestamp with time zone,
    published_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    round_robin_legs smallint DEFAULT 1 NOT NULL,
    max_teams_per_group integer,
    knockout_decision_method character varying(40) DEFAULT 'PENALTIES_ONLY'::character varying NOT NULL,
    extra_time_minutes smallint DEFAULT 30 NOT NULL,
    planned_pitch_count smallint DEFAULT 1 NOT NULL,
    playable_hours_per_day numeric(4,1) DEFAULT 8 NOT NULL,
    competition_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tournament_rules_advance_check CHECK ((advancing_teams_per_group > 0)),
    CONSTRAINT tournament_rules_complaint_check CHECK ((complaint_window_hours > 0)),
    CONSTRAINT tournament_rules_discipline_check CHECK (((yellow_cards_for_suspension > 0) AND (suspension_matches > 0))),
    CONSTRAINT tournament_rules_duration_check CHECK ((match_duration_minutes > 0)),
    CONSTRAINT tournament_rules_extra_time_check CHECK (((extra_time_minutes >= 1) AND (extra_time_minutes <= 60))),
    CONSTRAINT tournament_rules_forfeit_check CHECK (((forfeit_policy)::text = ANY ((ARRAY['ORGANIZER_DECISION'::character varying, 'WALKOVER'::character varying, 'NO_AUTOMATIC_RESULT'::character varying])::text[]))),
    CONSTRAINT tournament_rules_forfeit_score_check CHECK (((forfeit_winner_score >= 0) AND (forfeit_loser_score >= 0))),
    CONSTRAINT tournament_rules_group_capacity_check CHECK (((max_teams_per_group IS NULL) OR (max_teams_per_group >= 2))),
    CONSTRAINT tournament_rules_knockout_decision_check CHECK (((knockout_decision_method)::text = ANY ((ARRAY['PENALTIES_ONLY'::character varying, 'EXTRA_TIME_THEN_PENALTIES'::character varying])::text[]))),
    CONSTRAINT tournament_rules_pitch_count_check CHECK (((planned_pitch_count >= 1) AND (planned_pitch_count <= 30))),
    CONSTRAINT tournament_rules_playable_hours_check CHECK (((playable_hours_per_day >= (1)::numeric) AND (playable_hours_per_day <= (24)::numeric))),
    CONSTRAINT tournament_rules_points_check CHECK (((points_for_win >= 0) AND (points_for_draw >= 0) AND (points_for_loss >= 0))),
    CONSTRAINT tournament_rules_rest_check CHECK ((minimum_rest_minutes >= 30)),
    CONSTRAINT tournament_rules_round_legs_check CHECK ((round_robin_legs = ANY (ARRAY[1, 2])))
);


ALTER TABLE public.tournament_rules OWNER TO sfl;

--
-- Name: tournament_workflow_state; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournament_workflow_state (
    tournament_id uuid NOT NULL,
    current_step smallint DEFAULT 1 NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_workflow_state_current_step_check CHECK (((current_step >= 1) AND (current_step <= 8)))
);


ALTER TABLE public.tournament_workflow_state OWNER TO sfl;

--
-- Name: tournaments; Type: TABLE; Schema: public; Owner: sfl
--

CREATE TABLE public.tournaments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(255) NOT NULL,
    description text,
    status character varying(50) DEFAULT 'DRAFT'::character varying NOT NULL,
    location character varying(255),
    organizer_name character varying(255),
    organizer_contact_name character varying(255),
    organizer_email character varying(255),
    organizer_phone character varying(50),
    scope character varying(30) DEFAULT 'INTER_SCHOOL'::character varying NOT NULL,
    football_format smallint DEFAULT 7 NOT NULL,
    competition_format character varying(40) DEFAULT 'ROUND_ROBIN'::character varying NOT NULL,
    min_teams integer DEFAULT 2 NOT NULL,
    max_teams integer DEFAULT 32 NOT NULL,
    min_players integer DEFAULT 7 NOT NULL,
    max_players_per_team integer DEFAULT 25 NOT NULL,
    start_date date,
    end_date date,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    allowed_institution_levels text[] DEFAULT ARRAY['UNIVERSITY'::text, 'COLLEGE'::text] NOT NULL,
    all_institutions_allowed boolean DEFAULT true NOT NULL,
    default_max_teams_per_institution integer,
    organizing_institution_id uuid,
    min_goalkeepers integer DEFAULT 1 NOT NULL,
    CONSTRAINT tournaments_competition_format_check CHECK (((competition_format)::text = ANY ((ARRAY['ROUND_ROBIN'::character varying, 'GROUP_AND_KNOCKOUT'::character varying, 'KNOCKOUT'::character varying])::text[]))),
    CONSTRAINT tournaments_dates_check CHECK ((((start_date IS NULL) AND (end_date IS NULL)) OR ((start_date IS NOT NULL) AND (end_date IS NOT NULL) AND (start_date <= end_date)))),
    CONSTRAINT tournaments_football_format_check CHECK ((football_format = ANY (ARRAY[5, 7, 11]))),
    CONSTRAINT tournaments_institution_levels_check CHECK ((allowed_institution_levels <@ ARRAY['UNIVERSITY'::text, 'COLLEGE'::text])),
    CONSTRAINT tournaments_institution_limit_check CHECK (((default_max_teams_per_institution IS NULL) OR (default_max_teams_per_institution > 0))),
    CONSTRAINT tournaments_max_teams_check CHECK ((max_teams > 0)),
    CONSTRAINT tournaments_min_goalkeepers_check CHECK (((min_goalkeepers >= 0) AND (min_goalkeepers <= max_players_per_team))),
    CONSTRAINT tournaments_player_limits_check CHECK (((min_players >= football_format) AND (max_players_per_team >= min_players))),
    CONSTRAINT tournaments_scope_check CHECK (((scope)::text = ANY ((ARRAY['SINGLE_INSTITUTION'::character varying, 'INTER_SCHOOL'::character varying])::text[]))),
    CONSTRAINT tournaments_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'OPEN_REGISTRATION'::character varying, 'REGISTRATION_CLOSED'::character varying, 'ROSTER_LOCKED'::character varying, 'PREPARING'::character varying, 'IN_PROGRESS'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT tournaments_team_limits_check CHECK (((min_teams > 0) AND (max_teams >= min_teams)))
);


ALTER TABLE public.tournaments OWNER TO sfl;

